import { Navigate, Outlet } from 'react-router-dom';
import { useSelector } from 'react-redux';

// A Wrapper Component for Protected Routes
const RequireAuth = () => {
  // Ask Redux if the user is allowed in
  const isLoggedIn = useSelector((state) => state.auth.isLoggedIn);

  if (!isLoggedIn) {
    // If not logged in, kick them to the login page.
    // We use 'replace' to prevent them from hitting the back button.
    return <Navigate to="/login" replace />;
  }

  // If logged in, render the child routes (the actual page they wanted)!
  return <Outlet />;
};

/*
  Usage in Router:
  <Route element={<RequireAuth />}>
    <Route path="/dashboard" element={<Dashboard />} />
    <Route path="/settings" element={<Settings />} />
  </Route>
*/
